def run_dag(tasks, dependencies):
    completed = set()
    results = {}
    execution_order = []
    while len(completed) < len(tasks):
        progress = False
        for task_name, func in tasks.items():
            if task_name in completed:
                continue
            deps = dependencies.get(task_name, [])
            if all(d in completed for d in deps):
                results[task_name] = func(results)
                completed.add(task_name)
                execution_order.append(task_name)
                progress = True
        if not progress:
            break
    return results, execution_order

