def multi_strategy(data, strategies):
    outcomes = {}
    for name, fn in strategies.items():
        try:
            outcomes[name] = fn(data)
        except Exception as e:
            outcomes[name] = {"error": str(e)}
    best = max(
        (k for k in outcomes if "error" not in outcomes[k]),
        key=lambda k: outcomes[k].get("score", 0)
    )
    return best, outcomes[best]["score"]

